import { cn } from '@/lib/utils'

/**
 * Kininaru brand mark — interlocking K + P monogram (2026 refresh).
 *
 * The mark is now a raster image (sage green K, lavender-to-blue
 * gradient P, coral sparkle) embedded as a base64 data URI so it
 * renders crisply at any size without needing separate asset files.
 *
 * ⚠️ The mark image lives in TWO places that must stay in sync:
 *   1. here (React component)
 *   2. `public/icon.svg` (the visual source for generated PNG icons)
 */

const MARK_DATA_URI =
  'data:image/png;base64,'

export function KinLogoMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 200 200"
      aria-hidden="true"
      className={cn('shrink-0', className)}
    >
      <image href={MARK_DATA_URI} width="200" height="200" />
    </svg>
  )
}

export function KinLogo({
  className,
  showWordmark = true,
  wordmarkClassName,
  markClassName,
  color = '#1A365D',
  variant = 'stack',
}: {
  className?: string
  showWordmark?: boolean
  wordmarkClassName?: string
  markClassName?: string
  /** Brand marine (navy) by default; surfaces can pass any color. */
  color?: string
  /** stack = wordmark below the monogram (brand lockup), row = beside it. */
  variant?: 'stack' | 'row'
}) {
  return (
    <span
      className={cn(
        'inline-flex select-none',
        variant === 'stack'
          ? 'flex-col items-center gap-1.5 text-center'
          : 'items-center gap-2.5',
        className
      )}
      style={{ color }}
    >
      <KinLogoMark
        className={cn(
          variant === 'stack' ? 'w-10 h-10' : 'w-8 h-8',
          markClassName
        )}
      />
      {showWordmark && (
        <span className={cn('flex flex-col', variant === 'stack' ? 'items-center' : 'items-start', wordmarkClassName)}>
          <span
            className={cn(
              '[font-family:var(--font-jakarta),ui-sans-serif,system-ui,sans-serif] font-semibold uppercase tracking-[0.18em] leading-none',
              variant === 'stack' ? 'text-lg' : 'text-sm'
            )}
          >
            kininaru
          </span>
          <span className="text-[0.55em] tracking-[0.25em] text-muted-foreground/70 mt-0.5">PLAN · FOCUS · GROW</span>
        </span>
      )}
    </span>
  )
}
